with matched_keys as (select dept_id, level from employees except all select dept_id, level from employees where hire_date >= '2025-07-01'), kept_rows as (select s.* from employees s inner join matched_keys k on s.dept_id = k.dept_id and s.level = k.level) select s.full_name, s.email, s.dept_id, s.manager_id, s.job_title, s.salary, s.hire_date, s.is_remote, s.level, (select sum(e2.salary) from employees e2 where e2.dept_id = s.dept_id) as sum_employee_salary from kept_rows s;
